+func TestConcurrentReaders(t *testing.T) {
+	const count = 1000
+	b := NewBuffer[int](Config{Capacity: count + 1})
+	defer b.Close()
+	var wg sync.WaitGroup
+	for i := 0; i < 8; i++ {
+		c := b.NewCursor()
+		wg.Add(1)
+		go func() {
+			defer wg.Done()
+			defer c.Close()
+			for want := 0; want < count; {
+				var out [17]int
+				n, err := c.Read(context.Background(), out[:])
+				if err != nil {
+					t.Errorf("read: %v", err)
+					return
+				}
+				for _, item := range out[:n] {
+					if item != want {
+						t.Errorf("got %d, want %d", item, want)
+						return
+					}
+					want++
+				}
+			}
+		}()
+	}
+	for i := 0; i < count; i++ {
+		b.Append(i)
+	}
